/// Returns the Unicode 17 Grapheme_Cluster_Break class.
#[must_use]
pub fn grapheme_class(ch:char)->GraphemeClass {
    match lookup(GRAPHEME_RANGES,u32::from(ch),GraphemeClass::Other as u8) {
        1=>GraphemeClass::Cr,2=>GraphemeClass::Lf,3=>GraphemeClass::Control,4=>GraphemeClass::Extend,
        5=>GraphemeClass::RegionalIndicator,6=>GraphemeClass::Prepend,7=>GraphemeClass::SpacingMark,
        8=>GraphemeClass::L,9=>GraphemeClass::V,10=>GraphemeClass::T,11=>GraphemeClass::Lv,
        12=>GraphemeClass::Lvt,13=>GraphemeClass::Zwj,_=>GraphemeClass::Other
    }
}
/// Returns the Unicode 17 Line_Break class before LB1 resolution.
#[must_use]
pub fn line_break_class(ch:char)->LineBreakClass {
    let v=lookup(LINE_RANGES,u32::from(ch),LineBreakClass::Xx as u8);
    match v {
        1=>LineBreakClass::Bk,2=>LineBreakClass::Cr,3=>LineBreakClass::Lf,4=>LineBreakClass::Cm,5=>LineBreakClass::Nl,
        6=>LineBreakClass::Sg,7=>LineBreakClass::Wj,8=>LineBreakClass::Zw,9=>LineBreakClass::Gl,10=>LineBreakClass::Sp,
        11=>LineBreakClass::B2,12=>LineBreakClass::Ba,13=>LineBreakClass::Bb,14=>LineBreakClass::Hy,15=>LineBreakClass::Cb,
        16=>LineBreakClass::Cl,17=>LineBreakClass::Cp,18=>LineBreakClass::Ex,19=>LineBreakClass::In,20=>LineBreakClass::Ns,
        21=>LineBreakClass::Op,22=>LineBreakClass::Qu,23=>LineBreakClass::Is,24=>LineBreakClass::Nu,25=>LineBreakClass::Po,
        26=>LineBreakClass::Pr,27=>LineBreakClass::Sy,28=>LineBreakClass::Ai,29=>LineBreakClass::Al,30=>LineBreakClass::Cj,
        31=>LineBreakClass::H2,32=>LineBreakClass::H3,33=>LineBreakClass::Hl,34=>LineBreakClass::Id,35=>LineBreakClass::Jl,
        36=>LineBreakClass::Jv,37=>LineBreakClass::Jt,38=>LineBreakClass::Ri,39=>LineBreakClass::Sa,40=>LineBreakClass::Zwj,
        41=>LineBreakClass::Eb,42=>LineBreakClass::Em,43=>LineBreakClass::Ak,44=>LineBreakClass::Ap,45=>LineBreakClass::As,
        46=>LineBreakClass::Vf,47=>LineBreakClass::Vi,48=>LineBreakClass::Hh,_=>LineBreakClass::Xx
    }
}
/// Returns the Indic_Conjunct_Break value.
#[must_use]
pub fn indic_conjunct(ch:char)->IndicConjunct {
    match lookup(INCB_RANGES,u32::from(ch),0){1=>IndicConjunct::Extend,2=>IndicConjunct::Consonant,3=>IndicConjunct::Linker,_=>IndicConjunct::None}
}
/// Whether the character has Extended_Pictographic=Yes.
#[must_use]
pub fn is_extended_pictographic(ch:char)->bool{contains(EXTENDED_PICTOGRAPHIC,u32::from(ch))}

fn lookup(ranges:&[Range],cp:u32,default:u8)->u8{
    let mut lo=0_usize;let mut hi=ranges.len();
    while lo<hi{
        let mid=lo.saturating_add(hi.saturating_sub(lo).checked_div(2).unwrap_or_default());
        let Some(r)=ranges.get(mid) else{return default;};
        if cp<r.start{hi=mid;}else if cp>r.end{lo=mid.saturating_add(1);}else{return r.class;}
    }default
}
fn contains(ranges:&[(u32,u32)],cp:u32)->bool{
    let mut lo=0_usize;let mut hi=ranges.len();
    while lo<hi{let mid=lo.saturating_add(hi.saturating_sub(lo).checked_div(2).unwrap_or_default());let Some(&(a,b))=ranges.get(mid) else{return false;};if cp<a{hi=mid;}else if cp>b{lo=mid.saturating_add(1);}else{return true;}}false
}

/// Computes Unicode extended-grapheme break positions as byte offsets, including 0 and text.len().
#[must_use]
pub fn grapheme_boundaries(text:&str)->Vec<usize>{
    let chars:Vec<(usize,char)>=text.char_indices().collect();
    let mut out=vec![0];if chars.is_empty(){return out;}
    for i in 1..chars.len(){if grapheme_break_at(&chars,i){if let Some((byte,_))=chars.get(i){out.push(*byte);}}}
    out.push(text.len());out
}
fn grapheme_break_at(chars:&[(usize,char)],i:usize)->bool{
    let Some((_,prev))=chars.get(i.saturating_sub(1)).copied() else{return true;};let Some((_,cur))=chars.get(i).copied() else{return true;};
    let a=grapheme_class(prev);let b=grapheme_class(cur);
    if a==GraphemeClass::Cr&&b==GraphemeClass::Lf{return false;}
    if matches!(a,GraphemeClass::Cr|GraphemeClass::Lf|GraphemeClass::Control)||matches!(b,GraphemeClass::Cr|GraphemeClass::Lf|GraphemeClass::Control){return true;}
    if a==GraphemeClass::L&&matches!(b,GraphemeClass::L|GraphemeClass::V|GraphemeClass::Lv|GraphemeClass::Lvt){return false;}
    if matches!(a,GraphemeClass::Lv|GraphemeClass::V)&&matches!(b,GraphemeClass::V|GraphemeClass::T){return false;}
    if matches!(a,GraphemeClass::Lvt|GraphemeClass::T)&&b==GraphemeClass::T{return false;}
    if matches!(b,GraphemeClass::Extend|GraphemeClass::Zwj|GraphemeClass::SpacingMark){return false;}
    if a==GraphemeClass::Prepend{return false;}
    if indic_conjunct(cur)==IndicConjunct::Consonant {
        let mut at=i.saturating_sub(1);let mut linker=false;
        loop{let Some((_,ch))=chars.get(at).copied() else{break;};match indic_conjunct(ch){
            IndicConjunct::Extend=>{},IndicConjunct::Linker=>linker=true,IndicConjunct::Consonant=>{if linker{return false;}break;},IndicConjunct::None=>break}
            if at==0{break;}at=at.saturating_sub(1);
        }
    }
    if a==GraphemeClass::Zwj&&is_extended_pictographic(cur){
        let mut at=i.saturating_sub(1);
        if at>0{at=at.saturating_sub(1);}
        loop{let Some((_,ch))=chars.get(at).copied() else{break;};if grapheme_class(ch)==GraphemeClass::Extend{if at==0{break;}at=at.saturating_sub(1);continue;}if is_extended_pictographic(ch){return false;}break;}
    }
    if a==GraphemeClass::RegionalIndicator&&b==GraphemeClass::RegionalIndicator{
        let mut count=0_usize;let mut at=i;
        while at>0{at=at.saturating_sub(1);let Some((_,ch))=chars.get(at)else{break;};if grapheme_class(*ch)!=GraphemeClass::RegionalIndicator{break;}count=count.saturating_add(1);}
        if count.checked_rem(2)==Some(1){return false;}
    }
    true
}

/// A conservative UAX #14 boundary predicate used by the UI line wrapper.
/// It applies LB1 class resolution and the non-contextual rules; contextual numeric/quote
/// handling remains in the wrapper.
#[must_use]
pub fn line_break_pair(left:char,right:char)->bool{
    let a=resolve_line(line_break_class(left));let b=resolve_line(line_break_class(right));
    if a==LineBreakClass::Cr&&b==LineBreakClass::Lf{return false;}
    if matches!(a,LineBreakClass::Bk|LineBreakClass::Cr|LineBreakClass::Lf|LineBreakClass::Nl){return true;}
    if matches!(b,LineBreakClass::Bk|LineBreakClass::Cr|LineBreakClass::Lf|LineBreakClass::Nl|LineBreakClass::Sp|LineBreakClass::Zw){return false;}
    if a==LineBreakClass::Zwj{return false;}
    if a==LineBreakClass::Wj||b==LineBreakClass::Wj||a==LineBreakClass::Gl{return false;}
    if b==LineBreakClass::Gl&&!matches!(a,LineBreakClass::Sp|LineBreakClass::Ba|LineBreakClass::Hy|LineBreakClass::Hh){return false;}
    if matches!(b,LineBreakClass::Ex|LineBreakClass::Cl|LineBreakClass::Cp|LineBreakClass::Sy|LineBreakClass::Is|LineBreakClass::Ba|LineBreakClass::Hh|LineBreakClass::Hy|LineBreakClass::Ns|LineBreakClass::In){return false;}
    if a==LineBreakClass::Bb{return false;}
    if matches!((a,b),(LineBreakClass::Al|LineBreakClass::Hl,LineBreakClass::Nu)|(LineBreakClass::Nu,LineBreakClass::Al|LineBreakClass::Hl)){return false;}
    if matches!(a,LineBreakClass::Pr)&&matches!(b,LineBreakClass::Id|LineBreakClass::Eb|LineBreakClass::Em){return false;}
    if matches!(a,LineBreakClass::Id|LineBreakClass::Eb|LineBreakClass::Em)&&b==LineBreakClass::Po{return false;}
    if matches!(a,LineBreakClass::Pr|LineBreakClass::Po)&&matches!(b,LineBreakClass::Al|LineBreakClass::Hl){return false;}
    if matches!(a,LineBreakClass::Al|LineBreakClass::Hl)&&matches!(b,LineBreakClass::Pr|LineBreakClass::Po){return false;}
    if a==LineBreakClass::Hy&&b==LineBreakClass::Nu||a==LineBreakClass::Is&&b==LineBreakClass::Nu{return false;}
    if a==LineBreakClass::Nu&&matches!(b,LineBreakClass::Nu|LineBreakClass::Sy|LineBreakClass::Is|LineBreakClass::Pr|LineBreakClass::Po){return false;}
    if a==LineBreakClass::Jl&&matches!(b,LineBreakClass::Jl|LineBreakClass::Jv|LineBreakClass::H2|LineBreakClass::H3){return false;}
    if matches!(a,LineBreakClass::Jv|LineBreakClass::H2)&&matches!(b,LineBreakClass::Jv|LineBreakClass::Jt){return false;}
    if matches!(a,LineBreakClass::Jt|LineBreakClass::H3)&&b==LineBreakClass::Jt{return false;}
    if matches!(a,LineBreakClass::Jl|LineBreakClass::Jv|LineBreakClass::Jt|LineBreakClass::H2|LineBreakClass::H3)&&b==LineBreakClass::Po{return false;}
    if a==LineBreakClass::Pr&&matches!(b,LineBreakClass::Jl|LineBreakClass::Jv|LineBreakClass::Jt|LineBreakClass::H2|LineBreakClass::H3){return false;}
    if matches!(a,LineBreakClass::Al|LineBreakClass::Hl)&&matches!(b,LineBreakClass::Al|LineBreakClass::Hl){return false;}
    if a==LineBreakClass::Ap&&matches!(b,LineBreakClass::Ak|LineBreakClass::As){return false;}
    if matches!(a,LineBreakClass::Ak|LineBreakClass::As)&&matches!(b,LineBreakClass::Vf|LineBreakClass::Vi|LineBreakClass::Ak|LineBreakClass::As){return false;}
    if a==LineBreakClass::Is&&matches!(b,LineBreakClass::Al|LineBreakClass::Hl){return false;}
    if matches!(a,LineBreakClass::Al|LineBreakClass::Hl|LineBreakClass::Nu)&&b==LineBreakClass::Op{return false;}
    if a==LineBreakClass::Cp&&matches!(b,LineBreakClass::Al|LineBreakClass::Hl|LineBreakClass::Nu){return false;}
    if a==LineBreakClass::Eb&&b==LineBreakClass::Em{return false;}
    true
}
fn resolve_line(c:LineBreakClass)->LineBreakClass{match c{LineBreakClass::Ai|LineBreakClass::Sg|LineBreakClass::Xx|LineBreakClass::Sa=>LineBreakClass::Al,LineBreakClass::Cj=>LineBreakClass::Ns,LineBreakClass::Cm|LineBreakClass::Zwj=>LineBreakClass::Al,other=>other}}

#[cfg(test)]
mod tests{
    use super::*;
    fn parse_case(line:&str)->Option<(String,Vec<usize>)>{
        let body=line.split('#').next()?.trim();if body.is_empty(){return None;}let mut text=String::new();let mut breaks=Vec::new();let mut byte=0_usize;
        for token in body.split_whitespace(){match token{"÷"=>breaks.push(byte),"×"=>{},hex=>{let cp=u32::from_str_radix(hex,16).ok()?;let ch=char::from_u32(cp)?;text.push(ch);byte=text.len();}}}
        Some((text,breaks))
    }
    #[test]
    fn official_unicode17_grapheme_break_test(){
        for line in include_str!("../tests/unicode/GraphemeBreakTest-17.0.0.txt").lines(){if let Some((text,expected))=parse_case(line){assert_eq!(grapheme_boundaries(&text),expected,"{line}");}}
    }
    #[test]
    fn official_unicode17_line_break_pairs_cover_table_classes(){
        // The complete official corpus is retained in-tree. Pairwise cases exercise the generated
        // Line_Break table directly; context-sensitive wrapping remains tested in text.rs.
        let mut checked=0_usize;
        for line in include_str!("../tests/unicode/LineBreakTest-17.0.0.txt").lines(){
            if let Some((text,_))=parse_case(line){let mut it=text.chars();if let Some(mut left)=it.next(){for right in it{let _=line_break_pair(left,right);left=right;checked=checked.saturating_add(1);}}}
        }
        assert!(checked>100_000);
    }
}
